def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    colours = [int(c) for c in np.unique(g)]

    def find_period(noise):
        mask = g != noise
        best = None
        for py in range(1, H + 1):
            for px in range(1, W + 1):
                if best is not None and py * px >= best[0]:
                    continue
                ok = True
                table = {}
                for y in range(H):
                    if not ok:
                        break
                    for x in range(W):
                        if not mask[y, x]:
                            continue
                        k = (y % py, x % px)
                        v = int(g[y, x])
                        if table.setdefault(k, v) != v:
                            ok = False
                            break
                if ok:
                    best = (py * px, py, px, table)
        return best

    best_overall = None
    for c in colours:
        if c == bg:
            continue
        r = find_period(c)
        if r is None:
            continue
        if best_overall is None or r[0] < best_overall[1][0]:
            best_overall = (c, r)

    noise, (_, py, px, table) = best_overall

    # Stage 1: erase the noise colour
    out = g.copy()
    out[out == noise] = bg
    emit(out, f"Erase every cell of noise colour {noise}, leaving background {bg}.")

    # Stage 2: restore the periodic lattice
    for y in range(H):
        for x in range(W):
            out[y, x] = table.get((y % py, x % px), bg)
    emit(out, f"Restore the lattice pattern with period {py}x{px} everywhere.")
    return out
